package com.picviewer.app;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.os.Looper;import android.widget.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.util.concurrent.*;
@RunWith(RobolectricTestRunner.class) @org.robolectric.annotation.Config(sdk=34,qualifiers="w960dp-h600dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class DiscoveryTest {
 MainActivity a;String id="urn:uuid:fixture";
 @Before public void init(){a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void end(){a.onDestroy();}
 String reply(String types){return "<s:Envelope xmlns:s='"+PcDiscovery.SOAP+"' xmlns:a='"+PcDiscovery.ADDRESSING+"' xmlns:d='"+PcDiscovery.DISCOVERY+"' xmlns:p='"+PcDiscovery.COMPUTER+"'><s:Header><a:Action>"+PcDiscovery.DISCOVERY+"/ProbeMatches</a:Action><a:RelatesTo>"+id+"</a:RelatesTo></s:Header><s:Body><d:ProbeMatches><d:ProbeMatch><d:Types>"+types+"</d:Types><d:XAddrs>http://not-fetched.invalid/metadata</d:XAddrs></d:ProbeMatch></d:ProbeMatches></s:Body></s:Envelope>";}
 boolean parse(String xml)throws Exception{byte[] bytes=xml.getBytes(StandardCharsets.UTF_8);return PcDiscovery.reply(bytes,bytes.length,id);}
 @Test public void acceptsDifferentQNamePrefix()throws Exception{assertTrue(parse(reply("p:Computer").replace("xmlns:p=", "xmlns:alias=").replace("p:Computer","alias:Computer")));}
 @Test public void rejectsHelloAsSearchReply()throws Exception{assertFalse(parse(reply("p:Computer").replace("/ProbeMatches</a:Action>","/Hello</a:Action>")));}
 @Test public void acceptsCorrelatedComputerReply()throws Exception{assertTrue(parse(reply("p:Computer")));}
 @Test public void ignoresPrinter()throws Exception{assertFalse(parse(reply("p:Printer")));}
 @Test public void rejectsUnrelatedProbe()throws Exception{assertFalse(parse(reply("p:Computer").replace(id,"urn:uuid:other")));}
 @Test public void rejectsWrongNamespace()throws Exception{assertFalse(parse(reply("p:Computer").replace(PcDiscovery.COMPUTER,"urn:wrong")));}
 @Test public void rejectsDoctypeAndEntity()throws Exception{assertFalse(parse("<!DOCTYPE x [<!ENTITY y SYSTEM 'file:///not-read'>]>"+reply("p:Computer")));}
 @Test public void rejectsLargeReply()throws Exception{byte[] huge=new byte[PcDiscovery.MAX_PACKET+1];assertFalse(PcDiscovery.reply(huge,huge.length,id));}
 @Test public void subnetOnlyNoLoopbackMulticastBroadcast()throws Exception{InetAddress local=InetAddress.getByName("10.44.1.5");assertTrue(PcDiscovery.sameSubnet(local,24,InetAddress.getByName("10.44.1.8")));for(String s:new String[]{"10.44.2.8","10.44.1.255","10.44.1.0","127.0.0.1","239.255.255.250","10.44.1.5"})assertFalse(s,PcDiscovery.sameSubnet(local,24,InetAddress.getByName(s)));}
 @Test public void requestContainsComputerTypeAndId(){String probe=PcDiscovery.probe(id);assertTrue(probe.contains(id));assertTrue(probe.contains("p:Computer"));assertFalse(probe.contains("password"));}
 @Test public void connectionStartsWithNoAutomaticShareLogin(){a.connectionDialog();ConnectionDialog c=a.connectionUi;assertTrue(c.selected.isEmpty());assertNull(c.sharesJob);assertNull(c.discoveryJob);assertFalse(c.manual);assertEquals(android.view.View.GONE,c.advanced.getVisibility());}
 @Test public void findRequiresAccountBeforeRequest(){a.connectionDialog();ConnectionDialog c=a.connectionUi;c.host.setText("10.44.1.8");c.lookup();assertNull(c.sharesJob);assertTrue(c.status.getText().toString().contains("사용자명"));}
 @Test public void directShareFallbackRemains(){a.connectionDialog();ConnectionDialog c=a.connectionUi;c.host.setText("10.44.1.8");c.user.setText("fixture");c.pass.setText("synthetic-value");c.custom.setChecked(true);c.share.setText("photos");assertEquals("photos",c.input(true).share);assertEquals(445,c.input(true).port);}
 @Test public void changingHostInvalidatesShareSelection(){a.connectionDialog();ConnectionDialog c=a.connectionUi;c.selected="photos";c.host.setText("10.44.1.9");assertEquals("",c.selected);}
 @Test public void selectingShareDoesNotActivateOrAuthenticate(){a.connectionDialog();ConnectionDialog c=a.connectionUi;String source=a.config.source();c.showShares(Arrays.asList("photos","사진"));org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getListView().performItemClick(null,1,1);assertEquals("사진",c.selected);assertEquals(source,a.config.source());assertNull(c.sharesJob);}
 @Test public void dismissCancelsAndRejectsLateResults(){a.connectionDialog();ConnectionDialog c=a.connectionUi;int token=c.begin();c.sharesJob=new ShareBrowser.Job();ShareBrowser.Job job=c.sharesJob;c.dialog.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(job.cancelled.get());assertFalse(c.current(token));assertTrue(c.worker.isShutdown());}
 @Test public void cancelledEnumerationNeverConnects()throws Exception{ShareBrowser.Job job=new ShareBrowser.Job();job.close();try{ShareBrowser.find(new Config(),job);fail();}catch(java.io.InterruptedIOException expected){}}
 @Test public void connectionDialogRenders()throws Exception{a.connectionDialog();ConnectionDialog c=a.connectionUi;android.view.View v=c.dialog.getWindow().getDecorView();v.measure(android.view.View.MeasureSpec.makeMeasureSpec(760,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(560,1073741824));v.layout(0,0,760,560);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(760,560,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));java.io.File dir=new java.io.File(System.getProperty("picviewer.screenshots","build/screenshots"));dir.mkdirs();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(dir,"network-connection.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void discoverySelectionDoesNotSendCredentials(){a.connectionDialog();ConnectionDialog c=a.connectionUi;c.showComputers(Arrays.asList("10.44.1.8"));assertNull(c.sharesJob);assertNull(c.discoveryJob);assertFalse(c.host.getText().toString().contains("10.44"));}
 @Test public void sharesWrongPasswordShowsAuthNoRetry()throws Exception{Assume.assumeNotNull(System.getenv("PICVIEWER_TEST_PORT"));a.connectionDialog();ConnectionDialog c=a.connectionUi;c.host.setText("127.0.0.1");c.port.setText(System.getenv("PICVIEWER_TEST_PORT"));c.user.setText(System.getenv("PICVIEWER_TEST_USER"));c.pass.setText("wrong-fixture");c.lookup();c.worker.submit(()->{}).get(20,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(c.status.getText().toString().contains("계정/암호"));assertTrue(c.find.isEnabled());assertTrue(c.selected.isEmpty());}
 @Test public void sharedListingEndToEndFixtureInUi()throws Exception{Assume.assumeNotNull(System.getenv("PICVIEWER_TEST_PORT"));a.connectionDialog();ConnectionDialog c=a.connectionUi;c.host.setText("127.0.0.1");c.user.setText(System.getenv("PICVIEWER_TEST_USER"));c.pass.setText(System.getenv("PICVIEWER_TEST_PASSWORD"));c.port.setText(System.getenv("PICVIEWER_TEST_PORT"));c.lookup();c.worker.submit(()->{}).get(20,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(c.status.getText().toString().contains("공유"));android.app.AlertDialog list=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(list.getListView().getAdapter().getCount()>=1);list.getListView().performItemClick(null,0,0);assertTrue(c.selected.equalsIgnoreCase("photos"));}
}
